import { spawnSync } from 'node:child_process'
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterAll, describe, expect, it } from 'vitest'
import { telemetryDecoder } from './telemetry-decoder'

/**
 * Runs the real gr_satellites on audio generated by Direwolf's gen_packets, using a
 * throwaway AFSK AX.25 satellite definition. Skipped unless both tools are installed
 * (they are in the Docker base image: `docker run ... npx vitest run <this file>`).
 */
const installed = ['gr_satellites', 'gen_packets'].every(
  (tool) => spawnSync('which', [tool]).status === 0
)

const SATELLITE_YAML = `name: TEST-AFSK
norad: 99999
data:
  &tlm AX25 telemetry:
    telemetry: ax25
transmitters:
  1k2 AFSK downlink:
    frequency: 145.800e+6
    modulation: AFSK
    baudrate: 1200
    af_carrier: 1700
    deviation: 500
    framing: AX.25
    data:
    - *tlm
`

describe.skipIf(!installed)('telemetry decoder with real gr_satellites', () => {
  const dir = mkdtempSync(join(tmpdir(), 'tlm-int-'))
  afterAll(() => rmSync(dir, { recursive: true, force: true }))

  it('decodes every AX.25 packet from generated AFSK audio', async () => {
    // The demodulator loses the final packet when the audio ends right after it, so one
    // extra packet is appended and only the first 40 are expected.
    const packets = Array.from({ length: 41 }, (_, i) => `N0CALL>CQ,WIDE1-1:frame ${i} cubesat`)
    writeFileSync(join(dir, 'in.txt'), `${packets.join('\n')}\n`)
    writeFileSync(join(dir, 'sat.yml'), SATELLITE_YAML)
    const wav = join(dir, 'pass.wav')
    spawnSync('gen_packets', ['-o', wav, '-r', '48000', join(dir, 'in.txt')])

    const result = await telemetryDecoder.decode(wav, dir, {
      satelliteRef: join(dir, 'sat.yml'),
      iq: false,
      satellite: {
        name: 'TEST',
        noradId: 99999,
        signalConfig: { type: 'telemetry', bandwidth: 3000, sampleRate: 48000, demodulation: 'fm' },
      },
    })

    expect(result?.metadata?.frameCount).toBeGreaterThanOrEqual(40)
    const frames: { hex: string }[] = JSON.parse(
      readFileSync(join(dir, 'pass-frames.json'), 'utf8')
    ).frames
    const texts = frames.map((f) => Buffer.from(f.hex, 'hex').toString('latin1'))
    expect(texts[0]).toContain('frame 0 cubesat')
    expect(texts.some((t) => t.includes('frame 39 cubesat'))).toBe(true)
  }, 120_000)
})
